/* SampleTone - a sample-playback machine for the Digitone mk1 (OS 1.44).
 *
 * The Digitone has no sample engine and a machine cannot load a file at run
 * time, so the sample bytes are compiled in: samples.c is generated by bake.py
 * and this engine reads its table. That keeps the source replaceable: a future
 * +Drive loader only has to fill the same struct st_sample table from RAM.
 *
 * One mono one-shot per voice, with start/end (start after end plays
 * backwards), a loop mode, note pitch tracking and a tune offset. The AMP page
 * envelope and the note's velocity are the companion's, and the voice goes
 * through the stock filter, mixer and effects like FM.
 *
 * SYN2 H is a crusher (bit depth + sample rate reduction, OFF at the top of the
 * knob), and the two system LFOs reach the machine's knobs: they write a
 * destination slot and a signed modulation per voice, which FM applies to its
 * own voice and a machine has to add itself (see st_lfo below). The MACHINES
 * menu tile is st_icon; overlay.c holds the pages, the FUNC+turn defaults and
 * the key gating.
 *
 * MY_ID must equal mod.json's "dnmachine:81" claim. */
#include "digitone-mk1/machines.h"
#include "samples.h"

#define MY_ID 81
#define VOICES 8

/* ---- value text for the knobs --------------------------------------------------------------- */
static char *put_int(char *buf, int32_t v)
{
    char t[8];
    int32_t n = 0;
    if (v < 0) {
        *buf++ = '-';
        v = -v;
    }
    do {
        t[n++] = (char)('0' + v % 10);
        v /= 10;
    } while (v && n < 7);
    while (n)
        *buf++ = t[--n];
    *buf = 0;
    return buf;
}

/* SYN1 A, stock ALGO 0-7: the bottom half is one-shot, the top half loops. */
static void mode_text(int32_t value, char *buf)
{
    const char *s = (value >> 8) < 4 ? "ONE" : "LOOP";
    while ((*buf++ = *s++) != 0)
        ;
}

/* SYN1 E, stock HARM stored 37-89 (displayed -26..+26): semitones. */
static void pitch_text(int32_t value, char *buf)
{
    int32_t s = (value >> 8) - 63;
    if (s > 0)
        *buf++ = '+';
    put_int(buf, s);
}

static void percent_text(int32_t value, char *buf)
{
    char *end = put_int(buf, ((value >> 8) * 100) / 127);
    *end++ = '%';           /* after the digits, never over them */
    *end = 0;
}

/* SYN2 H: OFF at the top of the range, then the crusher's bit depth (12 down
 * to 2) as it turns down. */
static void crush_text(int32_t value, char *buf)
{
    int32_t r = value >> 8, c, bits;
    char *end;
    if (r < 0)
        r = 0;
    if (r >= 127) {
        buf[0] = 'O';
        buf[1] = 'F';
        buf[2] = 'F';
        buf[3] = 0;
        return;
    }
    c = 127 - r;
    bits = 12 - ((c - 1) * 10) / 126;   /* 12 down to 2 */
    end = put_int(buf, bits);
    *end++ = 'b';
    *end = 0;
}

static void sample_text(int32_t value, char *buf)
{
    uint32_t n = st_sample_count;
    uint32_t i = n ? (uint32_t)((value >> 8) * (int32_t)n) / 128u : 0;
    const char *s;
    if (i >= n)
        i = n ? n - 1 : 0;
    s = n ? st_samples[i].name : "NONE";
    while ((*buf++ = *s++) != 0)
        ;
}

/* ---- knobs ---------------------------------------------------------------------------------- */
/* SYN1 A-H then SYN2 A-H, each borrowing a stock parameter so p-locks, LFOs,
 * MIDI CC and presets keep working:
 *   A MODE  ALGO 0-7 (0-3 one-shot, 4-7 loop)
 *   B-D     unused: the FM ratio knobs still turn underneath (upstream limit)
 *   E PITCH HARM 37-89, displayed -26..+26 semitones
 *   F START DTUN 0-127
 *   G END   FDBK 0-127 (start above end plays backwards)
 *   H LEVEL MIX 0-127
 *   SYN2 A  SAMP 119: index into the compiled-in sample table
 *   SYN2 H  CRSH 126 (stock B Level, 0-127): crusher, OFF at the top, then
 *           12-bit/18 kHz down to 2-bit/2 kHz as it turns down
 *   SYN2 B-G unused (OPT/XFADE/STUT/CHAN are deferred; see README) */
const struct dnm_knob st_knobs[DNM_KNOBS] = {
    [0] = { "MODE", mode_text, 0 },
    [4] = { "PITCH", pitch_text, 0 },
    [5] = { "START", percent_text, 0 },
    [6] = { "END", percent_text, 0 },
    [7] = { "LEVEL", percent_text, 0 },
    [8] = { "SAMP", sample_text, 0 },
    [15] = { "CRSH", crush_text, 0 },
};

/* ---- tune ----------------------------------------------------------------------------------- */
/* 2^(semitones/12) in Q16 for HARM's 37..89, i.e. -26..+26 semitones. */
static const uint32_t st_tune[53] = {
    14596u, 15464u, 16384u, 17358u, 18390u, 19484u, 20643u, 21870u,
    23170u, 24548u, 26008u, 27554u, 29193u, 30929u, 32768u, 34716u,
    36781u, 38968u, 41285u, 43740u, 46341u, 49097u, 52016u, 55109u,
    58386u, 61858u, 65536u, 69433u, 73562u, 77936u, 82570u, 87480u,
    92682u, 98193u, 104032u, 110218u, 116772u, 123715u, 131072u, 138866u,
    147123u, 155872u, 165140u, 174960u, 185364u, 196386u, 208064u, 220436u,
    233544u, 247431u, 262144u, 277732u, 294247u,
};

/* ---- the LFOs ------------------------------------------------------------------------------- */
/* The firmware's two system LFOs modulate sound slots: each block it writes
 * DEST (a slot, 0-78) and MOD (8.8, signed) per voice into fw_lfo_state, then
 * adds them to its own working copy for FM. dnm_knob() reads the voice's
 * parameters after the locks and before the LFOs, so a machine has to add MOD
 * itself. FILTER, AMP and the FX destinations are applied downstream of the
 * voice and are deliberately left alone, or they would be applied twice.
 *
 * Clamps are the stock ranges, read from the firmware's own parameter records
 * on 1.44 (fw_params, 60 bytes an id): slot 17 ALGO 0-7, slot 21 HARM 37-89,
 * and slots 22, 23, 24, 27 and 34 all 0-127. A slot that is not one of ours is
 * never touched, and FM voices never enter this render, so FM's LFO keeps
 * working untouched. */
#define ST_SLOT_MODE  17
#define ST_SLOT_PITCH 21
#define ST_SLOT_START 22
#define ST_SLOT_END   23
#define ST_SLOT_LEVEL 24
#define ST_SLOT_SAMP  27
#define ST_SLOT_CRSH  34

static int32_t st_lfo(int32_t slot, int32_t val, int32_t mn, int32_t mx,
                       int32_t d0, int32_t m0, int32_t d1, int32_t m1)
{
    if (d0 == slot) {
        val += m0;
        if (val < mn)
            val = mn;
        else if (val > mx)
            val = mx;
    }
    if (d1 == slot) {
        val += m1;
        if (val < mn)
            val = mn;
        else if (val > mx)
            val = mx;
    }
    return val;
}

/* ---- voice state ---------------------------------------------------------------------------- */
static struct {
    int64_t pos;        /* 32.32 frame position in the selected sample */
    uint32_t samp;      /* index into st_samples[] */
    uint8_t active;
    uint32_t hold_acc;  /* crusher: sample-rate accumulator, 16.16 */
    int32_t hold_val;   /* crusher: the sample it holds */
} vst[VOICES];

/* 32x32 -> 64 in 16-bit pieces: gcc's m68k backend calls __muldi3 for any
 * 64-bit product, and core-dn1 does not export it. 16x16 products are native. */
static uint64_t st_mul32(uint32_t a, uint32_t b)
{
    uint32_t al = a & 0xffff, ah = a >> 16;
    uint32_t bl = b & 0xffff, bh = b >> 16;
    uint64_t lo = (uint32_t)(al * bl);
    uint64_t mid = (uint32_t)(al * bh) + (uint32_t)(ah * bl);
    uint64_t hi = (uint32_t)(ah * bh);
    return (hi << 32) + (mid << 16) + lo;
}

/* The generated table's kq16 is rate * 2^32 / (48000 * phase_inc(root)), Q16,
 * so this is frames an output sample, in 32.32. */
static uint64_t step_for(const struct st_sample *s, int32_t pitch, int32_t tune)
{
    uint32_t inc = dnm_phase_inc(pitch);
    uint64_t step = st_mul32(inc, s->kq16) >> 16;
    uint64_t hi = st_mul32((uint32_t)(step >> 16), st_tune[tune]);
    uint64_t lo = st_mul32((uint32_t)(step & 0xffff), st_tune[tune]);
    step = ((hi << 16) + lo) >> 16;
    return step ? step : 1;
}

static void bounds(const struct st_sample *s, int32_t sv, int32_t ev,
                   uint32_t *s0, uint32_t *e0)
{
    uint32_t last = s->frames ? s->frames - 1 : 0;
    uint32_t a = (last * (uint32_t)sv) / 127u;
    uint32_t b = (last * (uint32_t)ev) / 127u;
    if (a > last)
        a = last;
    if (b > last)
        b = last;
    if (a == b) {                       /* at least one frame of span */
        if (b + 1 < s->frames)
            b++;
        else if (a > 0)
            a--;
    }
    *s0 = a;
    *e0 = b;
}

/* ---- the engine ----------------------------------------------------------------------------- */
/* Interrupt level, 1500 blocks a second (~667 us): no unbounded loops, no allocation, bounded
 * stack. `block` is 32 samples Q1.31 and holds the FM voice's samples on entry. */
void st_render(int32_t voice, int32_t *block, const struct dnm_voice *v)
{
    int32_t vi = voice & (VOICES - 1);
    int32_t mode, start, end, level, tune, pick, crush, i;
    int32_t l0d, l0m, l1d, l1m;
    const struct st_sample *s;
    uint32_t s0, e0;
    int64_t pos, startpos, endpos, step;
    uint64_t step_u;
    int32_t dir, loop, navail, gain;
    int32_t cmask, do_crush;
    uint32_t cstep, hold_acc;
    int32_t hold_val;

    l0d = (int32_t)FW_LFO(vi, 0)[FW_LFO_DEST];
    l0m = (int32_t)FW_LFO(vi, 0)[FW_LFO_MOD];
    l1d = (int32_t)FW_LFO(vi, 1)[FW_LFO_DEST];
    l1m = (int32_t)FW_LFO(vi, 1)[FW_LFO_MOD];

    mode = st_lfo(ST_SLOT_MODE, dnm_knob(voice, 0), 0, 7 << 8,
                   l0d, l0m, l1d, l1m) >> 8;
    start = st_lfo(ST_SLOT_START, dnm_knob(voice, 5), 0, 127 << 8,
                    l0d, l0m, l1d, l1m) >> 8;
    end = st_lfo(ST_SLOT_END, dnm_knob(voice, 6), 0, 127 << 8,
                  l0d, l0m, l1d, l1m) >> 8;
    level = st_lfo(ST_SLOT_LEVEL, dnm_knob(voice, 7), 0, 127 << 8,
                    l0d, l0m, l1d, l1m) >> 8;
    tune = (st_lfo(ST_SLOT_PITCH, dnm_knob(voice, 4), 37 << 8, 89 << 8,
                    l0d, l0m, l1d, l1m) >> 8) - 37;
    pick = st_lfo(ST_SLOT_SAMP, dnm_knob(voice, 8), 0, 127 << 8,
                   l0d, l0m, l1d, l1m) >> 8;
    crush = st_lfo(ST_SLOT_CRSH, dnm_knob(voice, 15), 0, 127 << 8,
                    l0d, l0m, l1d, l1m) >> 8;

    if (tune < 0)
        tune = 0;
    if (tune > 52)
        tune = 52;

    /* Crusher: OFF at the top of the knob is a bit-exact bypass (no
     * mask, and the hold takes every sample). Turning down drops the depth from
     * 12 bits to 2 and the rate from 18 kHz to 2 kHz together. */
    do_crush = crush < 127;
    if (do_crush) {
        int32_t c = 127 - crush, bits, drop;
        if (c < 1)
            c = 1;
        bits = 12 - ((c - 1) * 10) / 126;   /* 12 down to 2 */
        drop = 16 - bits;
        cmask = (1 << drop) - 1;
        cstep = (uint32_t)(((uint32_t)(18000 - ((c - 1) * 16000) / 126)
                            * 1393u) >> 10);     /* rate / 48 kHz in Q16 */
    } else {
        cmask = 0;
        cstep = 1u << 16;
    }

    if (v->fresh) {
        uint32_t n = st_sample_count;
        uint32_t idx = n ? (uint32_t)(pick * (int32_t)n) / 128u : 0;
        if (idx >= n)
            idx = n ? n - 1 : 0;
        vst[vi].samp = idx;
        vst[vi].active = n ? 1 : 0;
        vst[vi].pos = 0;
        vst[vi].hold_acc = 1u << 16;    /* take a crusher sample at once */
        vst[vi].hold_val = 0;
    }

    if (!vst[vi].active || vst[vi].samp >= st_sample_count) {
        for (i = 0; i < 32; i++)
            block[i] = 0;
        return;
    }

    s = &st_samples[vst[vi].samp];
    if (!s->frames) {
        vst[vi].active = 0;
        for (i = 0; i < 32; i++)
            block[i] = 0;
        return;
    }
    bounds(s, start, end, &s0, &e0);
    startpos = (int64_t)((uint64_t)s0 << 32);
    endpos = (int64_t)((uint64_t)e0 << 32);
    dir = s0 <= e0 ? 1 : -1;
    loop = mode >= 4;

    /* A fresh note starts at START/SYN1-F (which is the high end for reverse);
     * a start/end turn mid-note keeps it alive but inside the new bounds. */
    pos = vst[vi].pos;
    if (v->fresh) {
        pos = startpos;
    } else if (dir > 0) {
        if (pos < startpos)
            pos = startpos;
        if (pos > endpos)
            pos = endpos;
    } else {
        if (pos > startpos)
            pos = startpos;
        if (pos < endpos)
            pos = endpos;
    }

    step_u = step_for(s, v->pitch, tune);
    step = (int64_t)step_u;             /* fits: 32.32 of 24 source frames */
    gain = (level * 4096) / 127;
    hold_acc = vst[vi].hold_acc;
    hold_val = vst[vi].hold_val;

    navail = 32;
    for (i = 0; i < 32; i++) {
        uint32_t idx, i0, i1;
        int32_t a, b, smp;

        /* Stop on the position, not the index: the last frame is inclusive and
         * the step is fractional. Signed, so a reverse underflow cannot wrap. */
        if (dir > 0 ? pos >= endpos : pos <= endpos) {
            i0 = e0;
            i1 = e0;
        } else {
            idx = (uint32_t)(pos >> 32);
            i0 = idx < s->frames ? idx : s->frames - 1;
            i1 = idx + 1 < s->frames ? idx + 1 : i0;
        }
        a = s->pcm[i0];
        b = s->pcm[i1];
        smp = a;
        if (i1 != i0) {
            int32_t d = b - a;
            uint32_t ad = d < 0 ? (uint32_t)(-d) : (uint32_t)d;
            uint32_t m = (uint32_t)(st_mul32(ad, (uint32_t)pos) >> 32);
            smp = a + (d < 0 ? -(int32_t)m : (int32_t)m);
        }
        if (do_crush) {
            smp &= ~cmask;              /* bit depth */
            hold_acc += cstep;          /* sample rate: hold it for a while */
            if (hold_acc >= (1u << 16)) {
                hold_acc -= 1u << 16;
                hold_val = smp;
            }
            smp = hold_val;
        } else {
            hold_val = smp;             /* OFF: keep the hold fresh */
        }
        block[i] = smp * gain;

        pos += dir > 0 ? step : -step;
        if (dir > 0 ? pos > endpos : pos < endpos) {
            if (loop)
                pos = startpos;
            else {
                vst[vi].active = 0;
                navail = i + 1;
                break;
            }
        }
    }
    vst[vi].pos = pos;
    vst[vi].hold_acc = hold_acc;
    vst[vi].hold_val = hold_val;
    for (i = navail; i < 32; i++)
        block[i] = 0;
}

/* ---- the icon ------------------------------------------------------------------------------- */
/* The MACHINES menu tile: 16 rows of 16 pixels, the top row first and bit 15
 * the left pixel (machines.h). The owner's 16x16 art, whose glyph occupies
 * rows 1-14 of the canvas: a small triangle beside a larger one, mirrored
 * about two full rows -- a sample and its tone. */
static const uint16_t st_icon[16] = {
    0x0000, 0x0000, 0x1000, 0x1840, 0x1C60, 0x1E70, 0x1F78, 0x7FFE,
    0x7FFE, 0x1F78, 0x1E70, 0x1C60, 0x1840, 0x1000, 0x0000, 0x0000,
};

/* ---- the descriptor ------------------------------------------------------------------------- */
/* No DNM_OWN_ENV: the machines companion applies the AMP page envelope and the
 * note's velocity. No DNM_PAGES2: the SYN second pages stay FM's. Defaults are
 * one 8.8 value per knob, -1 leaves the stock value alone; B-D and SYN2 B-G are
 * left alone so their FM parameters stay untouched on the way back to FM. */
/* 8.8, as machines.h documents: -1 leaves a knob alone. HARM 63 and 127 are
 * stored as 63.0 and 127.0 (not the raw knob numbers), so the tune starts at 0
 * semitones and END, LEVEL and CRSH start at the top of their range (CRSH's top
 * is OFF). overlay.c reads this for the knobs FUNC+turn resets, so the two
 * cannot drift apart. */
const int16_t st_defaults[DNM_KNOBS] = {
    0, -1, -1, -1, 63 << 8, 0, 127 << 8, 127 << 8, 0,
    -1, -1, -1, -1, -1, -1, 127 << 8,
};

const struct dnm_machine st_machine = {
    MY_ID, "SAMPLETONE", st_icon, st_knobs, st_render, 0, st_defaults,
};
